import React from 'react';
import { Box, Typography, Button } from '@mui/material';
import { CalendarToday } from '@mui/icons-material';  // Calendar icon import edildi

function CustomCard({ title, description, tags, buttonText, imageUrl, eventdate, lastdate }) {
  return (
    <Box
      sx={{
        width: '328px',
        height: '519px',
        display: 'flex',
        flexDirection: 'column',
        justifyContent: 'center',
        alignItems: 'center',
        padding: 0,
        backgroundColor: '#FFFFFF',
        border: '1px solid #293349',
        borderRadius: '16px 16px 0 0',
        boxSizing: 'border-box',
        margin: '10px',
        position: 'relative',
      }}
    >
      {/* Banner Image */}
      <Box
        sx={{
          display: 'flex',
          flexDirection: 'row',
          justifyContent: 'flex-end',
          alignItems: 'flex-start',
          padding: 'display: full',
          width: '40',
          height: '20px',
          backgroundImage: `url(${imageUrl})`,
          backgroundSize: 'cover',
          backgroundPosition: 'center',
          position: 'relative',
        }}
      >
        {/* Bookmark Icon */}
        <Box
          sx={{
            display: 'flex',
            justifyContent: 'center',
            alignItems: 'center',
            padding: '8px',
            width: '36px',
            height: '36px',
            backgroundColor: '#F6F8FF',
            borderRadius: '50%',
            position: 'absolute',
            top: '16px',
            right: '16px',
            zIndex: 1,
          }}
        >
          <Box sx={{ width: '20px', height: '20px' }} />
        </Box>
      </Box>

      {/* Content Area */}
      <Box
        sx={{
          display: 'flex',
          flexDirection: 'column',
          justifyContent: 'space-between',
          alignItems: 'center',
          padding: '16px',
          gap: '40px',
          width: '328px',
          height: '348px',
        }}
      >
        {/* Tags Section */}
        <Box sx={{ width: '296px', gap: '16px', display: 'flex', flexDirection: 'row', justifyContent: 'center' }}>
          {tags.map((tag, index) => (
            <Box
              key={index}
              sx={{
                display: 'flex',
                justifyContent: 'center',
                alignItems: 'center',
                padding: '4px 8px',
                width: '34px',
                height: '22px',
                border: '1px solid #293349',
                borderRadius: '16px',
              }}
            >
              <Typography sx={{ fontSize: '12px', color: '#293349' }}>{tag}</Typography>
            </Box>
          ))}
        </Box>

        {/* Event Date */}
        {eventdate && (
          <Box sx={{ width: '296px', display: 'flex', flexDirection: 'row', alignItems: 'center', gap: '4px' }}>
            <CalendarToday sx={{ color: '#1D1D1D', fontSize: '18px' }} /> {/* Calendar Icon */}
            <Typography sx={{ fontSize: '12px', color: '#1D1D1D' }}>{eventdate}</Typography> {/* Event Date */}
          </Box>
        )}

        {/* Title and Description */}
        <Box sx={{ width: '296px', gap: '16px', display: 'flex', flexDirection: 'column', alignItems: 'flex-start' }}>
          <Typography variant="h6" sx={{ fontWeight: '500', fontSize: '20px', color: '#1D1D1D' }}>
            {title}
          </Typography>
          <Typography sx={{ fontSize: '16px', color: '#878787' }}>
            {description}
          </Typography>
        </Box>

        {/* Date and Calendar Icon */}
        <Box sx={{ width: '296px', display: 'flex', flexDirection: 'row', alignItems: 'center', gap: '4px' }}>
          <CalendarToday sx={{ color: '#1D1D1D', fontSize: '18px' }} /> {/* Calendar Icon */}
          <Typography sx={{ fontSize: '12px', color: '#1D1D1D' }}>{lastdate}</Typography> {/* Last Date */}
        </Box>

        {/* Button */}
        <Box sx={{ width: '296px', display: 'flex', flexDirection: 'column', alignItems: 'center', gap: '8px' }}>
          <Button
            variant="contained"
            sx={{
              backgroundColor: '#00C26D',
              borderRadius: '4px',
              padding: '4px 52px',
              color: '#FFFFFF',
            }}
          >
            {buttonText}
          </Button>
        </Box>
      </Box>
    </Box>
  );
}

export default CustomCard;
